package ae.linalg;

import java.util.List;

/** Result of solving {@code A x = b}. */
public sealed interface Solution {
    /** Exactly one solution. */
    record Unique(Rational[] x) implements Solution { }

    /** Infinitely many: {@code particular + sum t_i * nullBasis[i]}; particular is 0 in every free column. */
    record Infinite(Rational[] particular, List<Rational[]> nullBasis) implements Solution { }

    /** No solution. */
    record Inconsistent() implements Solution { }
}

package ae.linalg;

import java.math.BigInteger;
import java.util.Objects;

/** Immutable exact fraction. Invariant: {@code den > 0} and {@code gcd(|num|, den) == 1}. */
public final class Rational implements Comparable<Rational> {
    public static final Rational ZERO = new Rational(BigInteger.ZERO, BigInteger.ONE);
    public static final Rational ONE = new Rational(BigInteger.ONE, BigInteger.ONE);

    private final BigInteger num;
    private final BigInteger den;

    private Rational(BigInteger num, BigInteger den) {
        this.num = num;
        this.den = den;
    }

    /** Single normalising factory; every other operation goes through it. */
    public static Rational of(BigInteger n, BigInteger d) {
        Objects.requireNonNull(n);
        Objects.requireNonNull(d);
        if (d.signum() == 0) {
            throw new ArithmeticException("zero denominator");
        }
        if (n.signum() == 0) {
            return ZERO;
        }
        BigInteger g = n.gcd(d);
        BigInteger nn = n.divide(g);
        BigInteger dd = d.divide(g);
        if (dd.signum() < 0) {
            nn = nn.negate();
            dd = dd.negate();
        }
        return new Rational(nn, dd);
    }

    public static Rational of(long n, long d) {
        return of(BigInteger.valueOf(n), BigInteger.valueOf(d));
    }

    public static Rational of(long n) {
        return of(BigInteger.valueOf(n), BigInteger.ONE);
    }

    public BigInteger num() {
        return num;
    }

    public BigInteger den() {
        return den;
    }

    public boolean isZero() {
        return num.signum() == 0;
    }

    public int signum() {
        return num.signum();
    }

    public Rational add(Rational o) {
        return of(num.multiply(o.den).add(o.num.multiply(den)), den.multiply(o.den));
    }

    public Rational sub(Rational o) {
        return of(num.multiply(o.den).subtract(o.num.multiply(den)), den.multiply(o.den));
    }

    public Rational mul(Rational o) {
        return of(num.multiply(o.num), den.multiply(o.den));
    }

    public Rational div(Rational o) {
        if (o.isZero()) {
            throw new ArithmeticException("division by zero");
        }
        return of(num.multiply(o.den), den.multiply(o.num));
    }

    public Rational negate() {
        return new Rational(num.negate(), den);
    }

    public Rational inverse() {
        return ONE.div(this);
    }

    /** Integer power; negative exponents invert first, so {@code ZERO.pow(-1)} throws. */
    public Rational pow(int e) {
        if (e < 0) {
            return inverse().pow(-e);
        }
        Rational result = ONE;
        Rational base = this;
        int k = e;
        while (k > 0) {
            if ((k & 1) == 1) {
                result = result.mul(base);
            }
            base = base.mul(base);
            k >>= 1;
        }
        return result;
    }

    @Override
    public int compareTo(Rational o) {
        return num.multiply(o.den).compareTo(o.num.multiply(den));
    }

    @Override
    public boolean equals(Object o) {
        return o instanceof Rational r && num.equals(r.num) && den.equals(r.den);
    }

    @Override
    public int hashCode() {
        return 31 * num.hashCode() + den.hashCode();
    }

    @Override
    public String toString() {
        return den.equals(BigInteger.ONE) ? num.toString() : num + "/" + den;
    }
}

package ae.linalg;

/** Thrown when an operation needs a non-singular matrix. */
public class SingularMatrixException extends ArithmeticException {
    private static final long serialVersionUID = 1L;

    public SingularMatrixException(String message) {
        super(message);
    }
}

package ae.linalg;

/** PA = LU with "first non-zero pivot" row selection. Works for singular matrices too. */
public record Lu(Matrix p, Matrix l, Matrix u, int sign) {

    public static Lu decompose(Matrix m) {
        m.requireSquare();
        int n = m.rows();
        Rational[][] u = m.copyGrid();
        Rational[][] l = new Rational[n][n];
        int[] perm = new int[n];
        for (int i = 0; i < n; i++) {
            perm[i] = i;
            for (int j = 0; j < n; j++) {
                l[i][j] = Rational.ZERO;
            }
        }
        int sign = 1;
        for (int c = 0; c < n; c++) {
            int p = c;
            while (p < n && u[p][c].isZero()) {
                p++;
            }
            if (p == n) {
                continue; // zero column from row c down: nothing to eliminate
            }
            if (p != c) {
                Rational[] t = u[p];
                u[p] = u[c];
                u[c] = t;
                t = l[p];
                l[p] = l[c];
                l[c] = t;
                int pi = perm[p];
                perm[p] = perm[c];
                perm[c] = pi;
                sign = -sign;
            }
            for (int i = c + 1; i < n; i++) {
                Rational f = u[i][c].div(u[c][c]);
                l[i][c] = f;
                for (int j = c; j < n; j++) {
                    u[i][j] = u[i][j].sub(f.mul(u[c][j]));
                }
            }
        }
        for (int i = 0; i < n; i++) {
            l[i][i] = Rational.ONE;
        }
        Rational[][] pg = new Rational[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                pg[i][j] = perm[i] == j ? Rational.ONE : Rational.ZERO;
            }
        }
        return new Lu(Matrix.ofRational(pg), Matrix.ofRational(l), Matrix.ofRational(u), sign);
    }

    public Rational determinant() {
        Rational d = sign < 0 ? Rational.of(-1) : Rational.ONE;
        for (int i = 0; i < u.rows(); i++) {
            d = d.mul(u.get(i, i));
        }
        return d;
    }

    /** Solve A x = b via forward and back substitution. */
    public Rational[] solve(Rational[] b) {
        int n = u.rows();
        if (b.length != n) {
            throw new IllegalArgumentException("rhs length " + b.length + " != " + n);
        }
        for (int i = 0; i < n; i++) {
            if (u.get(i, i).isZero()) {
                throw new SingularMatrixException("matrix is singular");
            }
        }
        Rational[] pb = p.apply(b);
        Rational[] y = new Rational[n];
        for (int i = 0; i < n; i++) {
            Rational s = pb[i];
            for (int j = 0; j < i; j++) {
                s = s.sub(l.get(i, j).mul(y[j]));
            }
            y[i] = s;
        }
        Rational[] x = new Rational[n];
        for (int i = n - 1; i >= 0; i--) {
            Rational s = y[i];
            for (int j = i + 1; j < n; j++) {
                s = s.sub(u.get(i, j).mul(x[j]));
            }
            x[i] = s.div(u.get(i, i));
        }
        return x;
    }
}

package ae.linalg;

import java.util.ArrayList;
import java.util.List;

/** Gauss-Jordan based algorithms over exact rationals. */
public final class Elimination {
    private Elimination() { }

    /** Reduced row echelon form and the pivot column of each non-zero row. */
    public record Rref(Matrix matrix, List<Integer> pivots) { }

    public static Rref rref(Matrix m) {
        Rational[][] g = m.copyGrid();
        List<Integer> pivots = new ArrayList<>();
        int r = 0;
        for (int c = 0; c < m.cols() && r < m.rows(); c++) {
            int p = r;
            while (p < m.rows() && g[p][c].isZero()) {
                p++;
            }
            if (p == m.rows()) {
                continue;
            }
            Rational[] tmp = g[p];
            g[p] = g[r];
            g[r] = tmp;
            Rational inv = g[r][c].inverse();
            for (int j = 0; j < m.cols(); j++) {
                g[r][j] = g[r][j].mul(inv);
            }
            for (int i = 0; i < m.rows(); i++) {
                if (i != r && !g[i][c].isZero()) {
                    Rational f = g[i][c];
                    for (int j = 0; j < m.cols(); j++) {
                        g[i][j] = g[i][j].sub(f.mul(g[r][j]));
                    }
                }
            }
            pivots.add(c);
            r++;
        }
        return new Rref(Matrix.ofRational(g), List.copyOf(pivots));
    }

    public static int rank(Matrix m) {
        return rref(m).pivots().size();
    }

    /** Determinant by forward elimination with row swaps (sign tracked). */
    public static Rational determinant(Matrix m) {
        m.requireSquare();
        int n = m.rows();
        Rational[][] g = m.copyGrid();
        Rational det = Rational.ONE;
        for (int c = 0; c < n; c++) {
            int p = c;
            while (p < n && g[p][c].isZero()) {
                p++;
            }
            if (p == n) {
                return Rational.ZERO;
            }
            if (p != c) {
                Rational[] tmp = g[p];
                g[p] = g[c];
                g[c] = tmp;
                det = det.negate();
            }
            det = det.mul(g[c][c]);
            for (int i = c + 1; i < n; i++) {
                Rational f = g[i][c].div(g[c][c]);
                for (int j = c; j < n; j++) {
                    g[i][j] = g[i][j].sub(f.mul(g[c][j]));
                }
            }
        }
        return det;
    }

    public static Matrix inverse(Matrix m) {
        m.requireSquare();
        int n = m.rows();
        Rational[][] aug = new Rational[n][2 * n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                aug[i][j] = m.get(i, j);
                aug[i][n + j] = i == j ? Rational.ONE : Rational.ZERO;
            }
        }
        Rref r = rref(Matrix.ofRational(aug));
        if (r.pivots().size() < n || r.pivots().get(n - 1) >= n) {
            throw new SingularMatrixException("matrix is singular");
        }
        Rational[][] out = new Rational[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                out[i][j] = r.matrix().get(i, n + j);
            }
        }
        return Matrix.ofRational(out);
    }

    /** One basis vector per free column, in free-column order, 1 in its own free column. */
    public static List<Rational[]> nullspace(Matrix m) {
        Rref r = rref(m);
        List<Rational[]> basis = new ArrayList<>();
        for (int f = 0; f < m.cols(); f++) {
            if (r.pivots().contains(f)) {
                continue;
            }
            Rational[] x = zeros(m.cols());
            x[f] = Rational.ONE;
            for (int row = 0; row < r.pivots().size(); row++) {
                x[r.pivots().get(row)] = r.matrix().get(row, f).negate();
            }
            basis.add(x);
        }
        return basis;
    }

    /** The original columns sitting at the pivot positions. */
    public static List<Rational[]> columnSpaceBasis(Matrix m) {
        List<Rational[]> cols = new ArrayList<>();
        for (int p : rref(m).pivots()) {
            cols.add(m.col(p));
        }
        return cols;
    }

    public static Solution solve(Matrix a, Rational[] b) {
        if (b.length != a.rows()) {
            throw new IllegalArgumentException("rhs length " + b.length + " != rows " + a.rows());
        }
        int n = a.cols();
        Rational[][] aug = new Rational[a.rows()][n + 1];
        for (int i = 0; i < a.rows(); i++) {
            for (int j = 0; j < n; j++) {
                aug[i][j] = a.get(i, j);
            }
            aug[i][n] = b[i];
        }
        Rref r = rref(Matrix.ofRational(aug));
        if (r.pivots().contains(n)) {
            return new Solution.Inconsistent();
        }
        Rational[] particular = zeros(n);
        for (int row = 0; row < r.pivots().size(); row++) {
            particular[r.pivots().get(row)] = r.matrix().get(row, n);
        }
        if (r.pivots().size() == n) {
            return new Solution.Unique(particular);
        }
        return new Solution.Infinite(particular, nullspace(a));
    }

    static Rational[] zeros(int n) {
        Rational[] z = new Rational[n];
        java.util.Arrays.fill(z, Rational.ZERO);
        return z;
    }
}

package ae.linalg;

import java.math.BigInteger;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.TreeSet;

/** Characteristic polynomial, rational eigenvalues and eigenspaces. */
public final class CharPoly {
    private CharPoly() { }

    /**
     * Faddeev-LeVerrier: coefficients c[0..n] of det(xI - A) = sum c[k] x^k with c[n] = 1.
     * Recurrence: M_1 = I, c[n-k] = -tr(A M_k) / k, M_{k+1} = A M_k + c[n-k] I.
     */
    public static Rational[] coefficients(Matrix a) {
        a.requireSquare();
        int n = a.rows();
        Rational[] c = new Rational[n + 1];
        c[n] = Rational.ONE;
        Matrix mk = Matrix.identity(n);
        for (int k = 1; k <= n; k++) {
            Rational t = a.times(mk).trace();
            c[n - k] = t.negate().div(Rational.of(k));
            mk = a.times(mk).plus(Matrix.identity(n).times(c[n - k]));
        }
        return c;
    }

    /**
     * Distinct rational eigenvalues in ascending order mapped to algebraic multiplicity. Uses the rational-root
     * theorem on the integer-scaled polynomial; the constant and leading coefficients must fit in 62 bits.
     */
    public static Map<Rational, Integer> rationalEigenvalues(Matrix a) {
        Rational[] c = coefficients(a);
        Map<Rational, Integer> result = new TreeMap<>();
        int low = 0;
        while (low < c.length && c[low].isZero()) {
            low++;
        }
        if (low > 0) {
            result.put(Rational.ZERO, low);
        }
        // integer polynomial without the x^low factor
        BigInteger lcm = BigInteger.ONE;
        for (int k = low; k < c.length; k++) {
            lcm = lcm.divide(lcm.gcd(c[k].den())).multiply(c[k].den());
        }
        BigInteger constant = c[low].mul(Rational.of(lcm, BigInteger.ONE)).num();
        BigInteger lead = c[c.length - 1].mul(Rational.of(lcm, BigInteger.ONE)).num();
        if (c.length - low <= 1) {
            return result;
        }
        TreeSet<Rational> candidates = new TreeSet<>();
        for (long p : divisors(constant.abs())) {
            for (long q : divisors(lead.abs())) {
                candidates.add(Rational.of(p, q));
                candidates.add(Rational.of(-p, q));
            }
        }
        List<Rational> poly = new ArrayList<>();
        for (int k = low; k < c.length; k++) {
            poly.add(c[k]);
        }
        for (Rational cand : candidates) {
            int mult = 0;
            while (poly.size() > 1) {
                List<Rational> q = divideByLinear(poly, cand);
                if (q == null) {
                    break;
                }
                poly = q;
                mult++;
            }
            if (mult > 0) {
                result.put(cand, mult);
            }
        }
        return result;
    }

    /** Synthetic division of sum poly[k] x^k by (x - r); returns the quotient or null if the remainder is non-zero. */
    private static List<Rational> divideByLinear(List<Rational> poly, Rational r) {
        int deg = poly.size() - 1;
        Rational[] q = new Rational[deg];
        Rational carry = Rational.ZERO;
        for (int k = deg; k >= 1; k--) {
            carry = poly.get(k).add(carry.mul(r));
            q[k - 1] = carry;
        }
        Rational remainder = poly.get(0).add(carry.mul(r));
        if (!remainder.isZero()) {
            return null;
        }
        return List.of(q);
    }

    private static List<Long> divisors(BigInteger n) {
        long v = n.longValueExact();
        if (v <= 0 || n.bitLength() > 62) {
            throw new ArithmeticException("coefficient out of supported range: " + n);
        }
        List<Long> out = new ArrayList<>();
        for (long d = 1; d * d <= v; d++) {
            if (v % d == 0) {
                out.add(d);
                if (d != v / d) {
                    out.add(v / d);
                }
            }
        }
        return out;
    }

    /** Null space of A - lambda I (empty unless lambda is an eigenvalue). */
    public static List<Rational[]> eigenspace(Matrix a, Rational lambda) {
        a.requireSquare();
        return Elimination.nullspace(a.minus(Matrix.identity(a.rows()).times(lambda)));
    }
}

package ae.linalg;

import java.math.BigInteger;

/** Fraction-free integer determinant (Bareiss), independent of the rational code path. */
public final class Bareiss {
    private Bareiss() { }

    public static BigInteger determinant(long[][] a) {
        int n = a.length;
        if (n == 0) {
            throw new IllegalArgumentException("empty");
        }
        BigInteger[][] g = new BigInteger[n][n];
        for (int i = 0; i < n; i++) {
            if (a[i].length != n) {
                throw new IllegalArgumentException("not square");
            }
            for (int j = 0; j < n; j++) {
                g[i][j] = BigInteger.valueOf(a[i][j]);
            }
        }
        BigInteger prev = BigInteger.ONE;
        int sign = 1;
        for (int k = 0; k < n - 1; k++) {
            if (g[k][k].signum() == 0) {
                int s = k + 1;
                while (s < n && g[s][k].signum() == 0) {
                    s++;
                }
                if (s == n) {
                    return BigInteger.ZERO;
                }
                BigInteger[] tmp = g[s];
                g[s] = g[k];
                g[k] = tmp;
                sign = -sign;
            }
            for (int i = k + 1; i < n; i++) {
                for (int j = k + 1; j < n; j++) {
                    g[i][j] = g[i][j].multiply(g[k][k]).subtract(g[i][k].multiply(g[k][j])).divide(prev);
                }
            }
            prev = g[k][k];
        }
        BigInteger det = g[n - 1][n - 1];
        return sign < 0 ? det.negate() : det;
    }
}

package ae.linalg;

import java.util.ArrayList;
import java.util.List;

/** Exact Gram-Schmidt: orthogonal (not normalised) vectors, since norms are generally irrational. */
public final class GramSchmidt {
    private GramSchmidt() { }

    public static Rational dot(Rational[] x, Rational[] y) {
        if (x.length != y.length) {
            throw new IllegalArgumentException("lengths differ: " + x.length + " vs " + y.length);
        }
        Rational s = Rational.ZERO;
        for (int i = 0; i < x.length; i++) {
            s = s.add(x[i].mul(y[i]));
        }
        return s;
    }

    /** Orthogonal basis of the span of the input; vectors dependent on earlier ones are dropped. */
    public static List<Rational[]> orthogonalize(List<Rational[]> vectors) {
        List<Rational[]> out = new ArrayList<>();
        for (Rational[] v : vectors) {
            if (!out.isEmpty() && v.length != out.get(0).length) {
                throw new IllegalArgumentException("lengths differ");
            }
            Rational[] r = v.clone();
            for (Rational[] u : out) {
                Rational f = dot(v, u).div(dot(u, u));
                for (int i = 0; i < r.length; i++) {
                    r[i] = r[i].sub(f.mul(u[i]));
                }
            }
            boolean zero = true;
            for (Rational x : r) {
                zero &= x.isZero();
            }
            if (!zero) {
                out.add(r);
            }
        }
        return out;
    }

    /** Orthogonal projection of v onto the span of an orthogonal basis. */
    public static Rational[] project(Rational[] v, List<Rational[]> orthogonalBasis) {
        Rational[] p = Elimination.zeros(v.length);
        for (Rational[] u : orthogonalBasis) {
            Rational f = dot(v, u).div(dot(u, u));
            for (int i = 0; i < p.length; i++) {
                p[i] = p[i].add(f.mul(u[i]));
            }
        }
        return p;
    }
}

package ae.linalg;

import java.util.Arrays;

/** Immutable rows x cols matrix of {@link Rational}. */
public final class Matrix {
    private final Rational[][] a;
    private final int rows;
    private final int cols;

    private Matrix(Rational[][] a, int rows, int cols) {
        this.a = a;
        this.rows = rows;
        this.cols = cols;
    }

    public static Matrix of(long[][] raw) {
        if (raw.length == 0) {
            throw new IllegalArgumentException("no rows");
        }
        Rational[][] g = new Rational[raw.length][];
        for (int i = 0; i < raw.length; i++) {
            if (raw[i].length != raw[0].length) {
                throw new IllegalArgumentException("ragged rows");
            }
            g[i] = new Rational[raw[i].length];
            for (int j = 0; j < raw[i].length; j++) {
                g[i][j] = Rational.of(raw[i][j]);
            }
        }
        return ofRational(g);
    }

    /** Copies the grid; rejects empty and ragged input. */
    public static Matrix ofRational(Rational[][] raw) {
        if (raw.length == 0 || raw[0].length == 0) {
            throw new IllegalArgumentException("empty matrix");
        }
        Rational[][] g = new Rational[raw.length][];
        for (int i = 0; i < raw.length; i++) {
            if (raw[i].length != raw[0].length) {
                throw new IllegalArgumentException("ragged rows");
            }
            g[i] = raw[i].clone();
            for (Rational r : g[i]) {
                if (r == null) {
                    throw new IllegalArgumentException("null entry");
                }
            }
        }
        return new Matrix(g, g.length, g[0].length);
    }

    public static Matrix zero(int rows, int cols) {
        if (rows < 1 || cols < 1) {
            throw new IllegalArgumentException("dimensions must be >= 1");
        }
        Rational[][] g = new Rational[rows][cols];
        for (Rational[] row : g) {
            Arrays.fill(row, Rational.ZERO);
        }
        return new Matrix(g, rows, cols);
    }

    public static Matrix identity(int n) {
        Matrix m = zero(n, n);
        for (int i = 0; i < n; i++) {
            m.a[i][i] = Rational.ONE;
        }
        return m;
    }

    public int rows() {
        return rows;
    }

    public int cols() {
        return cols;
    }

    public boolean isSquare() {
        return rows == cols;
    }

    public Rational get(int i, int j) {
        if (i < 0 || i >= rows || j < 0 || j >= cols) {
            throw new IndexOutOfBoundsException("(" + i + "," + j + ") in " + rows + "x" + cols);
        }
        return a[i][j];
    }

    public Rational[] row(int i) {
        return a[i].clone();
    }

    public Rational[] col(int j) {
        Rational[] c = new Rational[rows];
        for (int i = 0; i < rows; i++) {
            c[i] = a[i][j];
        }
        return c;
    }

    public Matrix plus(Matrix o) {
        return zip(o, true);
    }

    public Matrix minus(Matrix o) {
        return zip(o, false);
    }

    private Matrix zip(Matrix o, boolean add) {
        if (rows != o.rows || cols != o.cols) {
            throw new IllegalArgumentException("dimension mismatch " + rows + "x" + cols + " vs " + o.rows + "x" + o.cols);
        }
        Rational[][] g = new Rational[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                g[i][j] = add ? a[i][j].add(o.a[i][j]) : a[i][j].sub(o.a[i][j]);
            }
        }
        return new Matrix(g, rows, cols);
    }

    public Matrix times(Rational k) {
        Rational[][] g = new Rational[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                g[i][j] = a[i][j].mul(k);
            }
        }
        return new Matrix(g, rows, cols);
    }

    public Matrix times(Matrix o) {
        if (cols != o.rows) {
            throw new IllegalArgumentException("inner dimensions differ: " + cols + " vs " + o.rows);
        }
        Rational[][] g = new Rational[rows][o.cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < o.cols; j++) {
                Rational s = Rational.ZERO;
                for (int k = 0; k < cols; k++) {
                    s = s.add(a[i][k].mul(o.a[k][j]));
                }
                g[i][j] = s;
            }
        }
        return new Matrix(g, rows, o.cols);
    }

    /** Matrix times column vector. */
    public Rational[] apply(Rational[] x) {
        if (x.length != cols) {
            throw new IllegalArgumentException("vector length " + x.length + " != " + cols);
        }
        Rational[] y = new Rational[rows];
        for (int i = 0; i < rows; i++) {
            Rational s = Rational.ZERO;
            for (int k = 0; k < cols; k++) {
                s = s.add(a[i][k].mul(x[k]));
            }
            y[i] = s;
        }
        return y;
    }

    public Matrix transpose() {
        Rational[][] g = new Rational[cols][rows];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                g[j][i] = a[i][j];
            }
        }
        return new Matrix(g, cols, rows);
    }

    public Rational trace() {
        requireSquare();
        Rational s = Rational.ZERO;
        for (int i = 0; i < rows; i++) {
            s = s.add(a[i][i]);
        }
        return s;
    }

    /** Square matrix to a non-negative power by repeated squaring. */
    public Matrix pow(int e) {
        requireSquare();
        if (e < 0) {
            throw new IllegalArgumentException("negative exponent");
        }
        Matrix result = identity(rows);
        Matrix base = this;
        int k = e;
        while (k > 0) {
            if ((k & 1) == 1) {
                result = result.times(base);
            }
            base = base.times(base);
            k >>= 1;
        }
        return result;
    }

    void requireSquare() {
        if (!isSquare()) {
            throw new IllegalArgumentException("matrix is " + rows + "x" + cols + ", not square");
        }
    }

    /** Mutable copy of the grid for algorithms in this package. */
    Rational[][] copyGrid() {
        Rational[][] g = new Rational[rows][];
        for (int i = 0; i < rows; i++) {
            g[i] = a[i].clone();
        }
        return g;
    }

    @Override
    public boolean equals(Object o) {
        return o instanceof Matrix m && rows == m.rows && cols == m.cols && Arrays.deepEquals(a, m.a);
    }

    @Override
    public int hashCode() {
        return Arrays.deepHashCode(a);
    }

    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < rows; i++) {
            if (i > 0) {
                sb.append('\n');
            }
            for (int j = 0; j < cols; j++) {
                if (j > 0) {
                    sb.append(' ');
                }
                sb.append(a[i][j]);
            }
        }
        return sb.toString();
    }
}

