package ae.linalg;

import static org.junit.jupiter.api.Assertions.*;

import java.math.BigInteger;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Random;
import org.junit.jupiter.api.Test;

/** Seeded randomised cross-checks; every routine is compared against an independent oracle. */
class PropertyTest {
    static long[][] random(Random rnd, int rows, int cols, int bound) {
        long[][] a = new long[rows][cols];
        for (long[] row : a) {
            for (int j = 0; j < cols; j++) {
                row[j] = rnd.nextInt(2 * bound + 1) - bound;
            }
        }
        return a;
    }

    /** Rank-deficient matrix: some rows are integer combinations of earlier rows. */
    static long[][] deficient(Random rnd, int n) {
        long[][] a = random(rnd, n, n, 3);
        for (int i = 1; i < n; i++) {
            if (rnd.nextInt(3) == 0) {
                int j = rnd.nextInt(i);
                long k = rnd.nextInt(5) - 2;
                for (int c = 0; c < n; c++) {
                    a[i][c] = k * a[j][c];
                }
            }
        }
        return a;
    }

    /** Laplace expansion along row 0: exponential, so only for n <= 5. */
    static BigInteger cofactor(long[][] a) {
        int n = a.length;
        if (n == 1) {
            return BigInteger.valueOf(a[0][0]);
        }
        BigInteger sum = BigInteger.ZERO;
        for (int c = 0; c < n; c++) {
            long[][] minor = new long[n - 1][n - 1];
            for (int i = 1; i < n; i++) {
                int cc = 0;
                for (int j = 0; j < n; j++) {
                    if (j != c) {
                        minor[i - 1][cc++] = a[i][j];
                    }
                }
            }
            BigInteger term = BigInteger.valueOf(a[0][c]).multiply(cofactor(minor));
            sum = (c % 2 == 0) ? sum.add(term) : sum.subtract(term);
        }
        return sum;
    }

    static Rational[] vec(Random rnd, int n) {
        Rational[] v = new Rational[n];
        for (int i = 0; i < n; i++) {
            v[i] = Rational.of(rnd.nextInt(9) - 4);
        }
        return v;
    }

    static boolean isZero(Rational[] v) {
        for (Rational r : v) {
            if (!r.isZero()) {
                return false;
            }
        }
        return true;
    }

    @Test
    void generatorsProduceSingularAndRegularMatrices() {
        Random rnd = new Random(1);
        int singular = 0;
        int regular = 0;
        for (int t = 0; t < 300; t++) {
            if (cofactor(deficient(rnd, 4)).signum() == 0) {
                singular++;
            } else {
                regular++;
            }
        }
        assertTrue(singular >= 30, "singular=" + singular);
        assertTrue(regular >= 30, "regular=" + regular);
    }

    @Test
    void determinantThreeWays() {
        Random rnd = new Random(2);
        for (int t = 0; t < 300; t++) {
            int n = 1 + rnd.nextInt(5);
            long[][] a = t % 2 == 0 ? random(rnd, n, n, 4) : deficient(rnd, n);
            BigInteger expected = cofactor(a);
            Matrix m = Matrix.of(a);
            Rational gauss = Elimination.determinant(m);
            assertEquals(Rational.of(expected.longValueExact()), gauss, "gauss " + m);
            assertEquals(expected, Bareiss.determinant(a), "bareiss " + m);
            assertEquals(gauss, Lu.decompose(m).determinant(), "lu " + m);
            assertEquals(gauss, Elimination.determinant(m.transpose()), "transpose " + m);
        }
    }

    @Test
    void determinantIsMultiplicative() {
        Random rnd = new Random(3);
        for (int t = 0; t < 100; t++) {
            int n = 2 + rnd.nextInt(3);
            Matrix a = Matrix.of(random(rnd, n, n, 3));
            Matrix b = Matrix.of(random(rnd, n, n, 3));
            assertEquals(Elimination.determinant(a).mul(Elimination.determinant(b)), Elimination.determinant(a.times(b)));
        }
    }

    @Test
    void inverseExistsExactlyWhenDeterminantNonZero() {
        Random rnd = new Random(4);
        int inverted = 0;
        int refused = 0;
        for (int t = 0; t < 300; t++) {
            int n = 1 + rnd.nextInt(5);
            Matrix a = Matrix.of(t % 2 == 0 ? random(rnd, n, n, 3) : deficient(rnd, n));
            if (Elimination.determinant(a).isZero()) {
                assertThrows(SingularMatrixException.class, () -> Elimination.inverse(a), a.toString());
                refused++;
            } else {
                Matrix inv = Elimination.inverse(a);
                assertEquals(Matrix.identity(n), a.times(inv), a.toString());
                assertEquals(Matrix.identity(n), inv.times(a), a.toString());
                inverted++;
            }
        }
        assertTrue(inverted > 30 && refused > 30, inverted + "/" + refused);
    }

    @Test
    void rankNullityAndNullspaceVectors() {
        Random rnd = new Random(5);
        for (int t = 0; t < 300; t++) {
            int r = 1 + rnd.nextInt(5);
            int c = 1 + rnd.nextInt(5);
            long[][] raw = random(rnd, r, c, 2);
            if (t % 3 == 0 && r > 1) {
                raw[r - 1] = raw[0].clone();
            }
            Matrix a = Matrix.of(raw);
            int rank = Elimination.rank(a);
            List<Rational[]> ns = Elimination.nullspace(a);
            assertEquals(c, rank + ns.size(), a.toString());
            assertEquals(rank, Elimination.rank(a.transpose()), "rank(A)=rank(A^T) " + a);
            assertEquals(rank, Elimination.columnSpaceBasis(a).size());
            for (Rational[] x : ns) {
                assertTrue(isZero(a.apply(x)), "A*n=0 for " + a);
                assertFalse(isZero(x));
            }
            // the basis is independent: its own rank equals its size
            if (!ns.isEmpty()) {
                Rational[][] rows = ns.toArray(new Rational[0][]);
                assertEquals(ns.size(), Elimination.rank(Matrix.ofRational(rows)), a.toString());
            }
        }
    }

    @Test
    void solveClassifiesAndVerifiesAgainstOracle() {
        Random rnd = new Random(6);
        int unique = 0;
        int infinite = 0;
        int inconsistent = 0;
        for (int t = 0; t < 400; t++) {
            int r = 1 + rnd.nextInt(4);
            int c = 1 + rnd.nextInt(4);
            Matrix a = Matrix.of(random(rnd, r, c, 2));
            Rational[] b = t % 2 == 0 ? a.apply(vec(rnd, c)) : vec(rnd, r);
            Solution s = Elimination.solve(a, b);
            int rank = Elimination.rank(a);
            // consistency oracle: rank([A|b]) == rank(A)
            Rational[][] aug = new Rational[r][c + 1];
            for (int i = 0; i < r; i++) {
                System.arraycopy(a.row(i), 0, aug[i], 0, c);
                aug[i][c] = b[i];
            }
            boolean consistent = Elimination.rank(Matrix.ofRational(aug)) == rank;
            switch (s) {
                case Solution.Unique u -> {
                    assertTrue(consistent && rank == c, a.toString());
                    assertArrayEquals(b, a.apply(u.x()));
                    unique++;
                }
                case Solution.Infinite inf -> {
                    assertTrue(consistent && rank < c, a.toString());
                    assertArrayEquals(b, a.apply(inf.particular()));
                    assertEquals(c - rank, inf.nullBasis().size());
                    for (Rational[] n : inf.nullBasis()) {
                        assertTrue(isZero(a.apply(n)));
                    }
                    infinite++;
                }
                case Solution.Inconsistent i -> {
                    assertFalse(consistent, a.toString());
                    inconsistent++;
                }
            }
        }
        assertTrue(unique >= 20 && infinite >= 20 && inconsistent >= 20, unique + "/" + infinite + "/" + inconsistent);
    }

    @Test
    void luReconstructsAndSolves() {
        Random rnd = new Random(7);
        for (int t = 0; t < 300; t++) {
            int n = 1 + rnd.nextInt(5);
            Matrix a = Matrix.of(t % 2 == 0 ? random(rnd, n, n, 4) : deficient(rnd, n));
            Lu lu = Lu.decompose(a);
            assertEquals(lu.p().times(a), lu.l().times(lu.u()), a.toString());
            for (int i = 0; i < n; i++) {
                assertEquals(Rational.ONE, lu.l().get(i, i));
                for (int j = i + 1; j < n; j++) {
                    assertEquals(Rational.ZERO, lu.l().get(i, j));
                }
                for (int j = 0; j < i; j++) {
                    assertEquals(Rational.ZERO, lu.u().get(i, j));
                }
            }
            if (!Elimination.determinant(a).isZero()) {
                Rational[] b = vec(rnd, n);
                assertArrayEquals(b, a.apply(lu.solve(b)), a.toString());
            }
        }
    }

    /** Evaluate a polynomial at a matrix with Horner's rule. */
    static Matrix evalAt(Rational[] coef, Matrix a) {
        Matrix acc = Matrix.zero(a.rows(), a.cols());
        for (int k = coef.length - 1; k >= 0; k--) {
            acc = acc.times(a).plus(Matrix.identity(a.rows()).times(coef[k]));
        }
        return acc;
    }

    @Test
    void cayleyHamiltonAndTraceDeterminantCoefficients() {
        Random rnd = new Random(8);
        for (int t = 0; t < 200; t++) {
            int n = 1 + rnd.nextInt(5);
            Matrix a = Matrix.of(random(rnd, n, n, 3));
            Rational[] c = CharPoly.coefficients(a);
            assertEquals(n + 1, c.length);
            assertEquals(Rational.ONE, c[n]);
            assertEquals(a.trace().negate(), c[n - 1], "trace " + a);
            Rational sign = n % 2 == 0 ? Rational.ONE : Rational.of(-1);
            assertEquals(Elimination.determinant(a).mul(sign), c[0], "det " + a);
            // Cayley-Hamilton: p(A) = 0
            assertEquals(Matrix.zero(n, n), evalAt(c, a), a.toString());
        }
    }

    @Test
    void eigenvectorsSatisfyDefinitionAndMultiplicitiesSumToDegree() {
        Random rnd = new Random(9);
        int withEigenvalues = 0;
        for (int t = 0; t < 200; t++) {
            int n = 2 + rnd.nextInt(3);
            // similar-to-diagonal-ish: triangular matrix so that eigenvalues are rational by construction
            long[][] raw = random(rnd, n, n, 2);
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < i; j++) {
                    raw[i][j] = 0;
                }
            }
            Matrix a = Matrix.of(raw);
            Map<Rational, Integer> ev = CharPoly.rationalEigenvalues(a);
            int total = 0;
            for (Map.Entry<Rational, Integer> e : ev.entrySet()) {
                total += e.getValue();
                List<Rational[]> basis = CharPoly.eigenspace(a, e.getKey());
                assertFalse(basis.isEmpty(), a + " lambda=" + e.getKey());
                assertTrue(basis.size() <= e.getValue(), "geometric <= algebraic");
                for (Rational[] x : basis) {
                    Rational[] ax = a.apply(x);
                    for (int i = 0; i < n; i++) {
                        assertEquals(e.getKey().mul(x[i]), ax[i], a + " lambda=" + e.getKey());
                    }
                }
            }
            // triangular: the eigenvalues are the diagonal, all rational
            assertEquals(n, total, a.toString());
            Map<Rational, Integer> diag = new java.util.TreeMap<>();
            for (int i = 0; i < n; i++) {
                diag.merge(a.get(i, i), 1, Integer::sum);
            }
            assertEquals(diag, new java.util.TreeMap<>(ev));
            withEigenvalues++;
        }
        assertEquals(200, withEigenvalues);
    }

    @Test
    void gramSchmidtIsOrthogonalAndSpansTheSame() {
        Random rnd = new Random(10);
        for (int t = 0; t < 200; t++) {
            int dim = 2 + rnd.nextInt(3);
            int count = 1 + rnd.nextInt(5);
            List<Rational[]> in = new ArrayList<>();
            for (int i = 0; i < count; i++) {
                in.add(vec(rnd, dim));
            }
            List<Rational[]> out = GramSchmidt.orthogonalize(in);
            for (int i = 0; i < out.size(); i++) {
                assertFalse(isZero(out.get(i)));
                for (int j = i + 1; j < out.size(); j++) {
                    assertEquals(Rational.ZERO, GramSchmidt.dot(out.get(i), out.get(j)));
                }
            }
            Matrix inM = Matrix.ofRational(in.toArray(new Rational[0][]));
            assertEquals(Elimination.rank(inM), out.size());
            // every input vector is reproduced by projecting onto the output basis
            for (Rational[] x : in) {
                assertArrayEquals(x, GramSchmidt.project(x, out));
            }
        }
    }
}

package ae.linalg;

import static org.junit.jupiter.api.Assertions.*;

import java.util.List;
import org.junit.jupiter.api.Test;

class EliminationTest {
    static Matrix m(long[]... rows) {
        return Matrix.of(rows);
    }

    static Rational[] v(long... xs) {
        Rational[] r = new Rational[xs.length];
        for (int i = 0; i < xs.length; i++) {
            r[i] = Rational.of(xs[i]);
        }
        return r;
    }

    @Test
    void rrefLiteralWithFreeColumn() {
        // columns: 0 pivot, 1 = 2*col0 (free), 2 pivot, 3 free
        Matrix a = m(new long[] {1, 2, 0, 3}, new long[] {2, 4, 1, 7}, new long[] {3, 6, 1, 10});
        Elimination.Rref r = Elimination.rref(a);
        assertEquals(List.of(0, 2), r.pivots());
        // row3 = row1 + row2 -> zero row. After reduction: [1 2 0 3], [0 0 1 1], [0 0 0 0]
        assertEquals(m(new long[] {1, 2, 0, 3}, new long[] {0, 0, 1, 1}, new long[] {0, 0, 0, 0}), r.matrix());
        assertEquals(2, Elimination.rank(a));
    }

    @Test
    void rrefNeedsRowSwapAndScaling() {
        Matrix a = m(new long[] {0, 2, 4}, new long[] {3, 0, 6});
        Elimination.Rref r = Elimination.rref(a);
        assertEquals(m(new long[] {1, 0, 2}, new long[] {0, 1, 2}), r.matrix());
        assertEquals(List.of(0, 1), r.pivots());
    }

    @Test
    void determinantLiterals() {
        assertEquals(Rational.of(-2), Elimination.determinant(m(new long[] {1, 2}, new long[] {3, 4})));
        // swap needed: leading zero. det = -(1*... ) computed by cofactor: 0*(..) - 2*(3*4-... )
        // [[0,2,1],[3,1,0],[1,0,2]] : 0*(2-0) - 2*(6-0) + 1*(0-1) = -12 - 1 = -13
        assertEquals(Rational.of(-13), Elimination.determinant(m(new long[] {0, 2, 1}, new long[] {3, 1, 0}, new long[] {1, 0, 2})));
        assertEquals(Rational.ZERO, Elimination.determinant(m(new long[] {1, 2}, new long[] {2, 4})));
        assertEquals(Rational.of(7), Elimination.determinant(m(new long[] {7})));
        assertEquals(Rational.ONE, Elimination.determinant(Matrix.identity(5)));
    }

    @Test
    void inverseLiteral() {
        Matrix a = m(new long[] {2, 1}, new long[] {5, 3});
        Matrix inv = Elimination.inverse(a);
        assertEquals(m(new long[] {3, -1}, new long[] {-5, 2}), inv);
        Matrix b = m(new long[] {1, 2}, new long[] {3, 4});
        Matrix invB = Elimination.inverse(b);
        assertEquals(Rational.of(-2), invB.get(0, 0));
        assertEquals(Rational.ONE, invB.get(0, 1));
        assertEquals(Rational.of(3, 2), invB.get(1, 0));
        assertEquals(Rational.of(-1, 2), invB.get(1, 1));
    }

    @Test
    void singularAndNonSquareInverseFail() {
        assertThrows(SingularMatrixException.class, () -> Elimination.inverse(m(new long[] {1, 2}, new long[] {2, 4})));
        assertThrows(IllegalArgumentException.class, () -> Elimination.inverse(Matrix.zero(2, 3)));
        assertThrows(IllegalArgumentException.class, () -> Elimination.determinant(Matrix.zero(2, 3)));
    }

    @Test
    void nullspaceLiteral() {
        Matrix a = m(new long[] {1, 2, 0, 3}, new long[] {2, 4, 1, 7}, new long[] {3, 6, 1, 10});
        List<Rational[]> basis = Elimination.nullspace(a);
        assertEquals(2, basis.size());
        // free columns 1 and 3. Rref rows: x0 + 2x1 + 3x3 = 0, x2 + x3 = 0
        assertArrayEquals(v(-2, 1, 0, 0), basis.get(0));
        assertArrayEquals(v(-3, 0, -1, 1), basis.get(1));
    }

    @Test
    void nullspaceOfFullRankIsEmptyAndZeroMatrixIsAll() {
        assertTrue(Elimination.nullspace(Matrix.identity(3)).isEmpty());
        List<Rational[]> all = Elimination.nullspace(Matrix.zero(2, 3));
        assertEquals(3, all.size());
        assertArrayEquals(v(1, 0, 0), all.get(0));
        assertArrayEquals(v(0, 1, 0), all.get(1));
        assertArrayEquals(v(0, 0, 1), all.get(2));
    }

    @Test
    void columnSpaceBasisTakesOriginalColumns() {
        Matrix a = m(new long[] {1, 2, 0, 3}, new long[] {2, 4, 1, 7}, new long[] {3, 6, 1, 10});
        List<Rational[]> cols = Elimination.columnSpaceBasis(a);
        assertEquals(2, cols.size());
        assertArrayEquals(v(1, 2, 3), cols.get(0));
        assertArrayEquals(v(0, 1, 1), cols.get(1));
    }

    @Test
    void solveUnique() {
        Matrix a = m(new long[] {2, 1}, new long[] {5, 3});
        Solution s = Elimination.solve(a, v(4, 11));
        Solution.Unique u = assertInstanceOf(Solution.Unique.class, s);
        // 2x+y=4, 5x+3y=11 -> x=1, y=2
        assertArrayEquals(v(1, 2), u.x());
    }

    @Test
    void solveInfiniteHasParticularWithZeroFreeColumns() {
        // x + 2y + z = 3 ; 2x + 4y + 3z = 8  -> pivots 0,2 ; free y
        Matrix a = m(new long[] {1, 2, 1}, new long[] {2, 4, 3});
        Solution.Infinite inf = assertInstanceOf(Solution.Infinite.class, Elimination.solve(a, v(3, 8)));
        // z = 2, x = 1 - 2y
        assertArrayEquals(v(1, 0, 2), inf.particular());
        assertEquals(1, inf.nullBasis().size());
        assertArrayEquals(v(-2, 1, 0), inf.nullBasis().get(0));
    }

    @Test
    void solveInconsistent() {
        Matrix a = m(new long[] {1, 1}, new long[] {2, 2});
        assertInstanceOf(Solution.Inconsistent.class, Elimination.solve(a, v(1, 3)));
        // control: same matrix, consistent right-hand side
        assertInstanceOf(Solution.Infinite.class, Elimination.solve(a, v(1, 2)));
    }

    @Test
    void solveOverdeterminedConsistent() {
        Matrix a = m(new long[] {1, 0}, new long[] {0, 1}, new long[] {1, 1});
        assertArrayEquals(v(2, 3), assertInstanceOf(Solution.Unique.class, Elimination.solve(a, v(2, 3, 5))).x());
        assertInstanceOf(Solution.Inconsistent.class, Elimination.solve(a, v(2, 3, 6)));
    }

    @Test
    void solveRejectsWrongRhsLength() {
        assertThrows(IllegalArgumentException.class, () -> Elimination.solve(Matrix.identity(2), v(1, 2, 3)));
    }

    @Test
    void bareissLiterals() {
        assertEquals(java.math.BigInteger.valueOf(-13), Bareiss.determinant(new long[][] {{0, 2, 1}, {3, 1, 0}, {1, 0, 2}}));
        assertEquals(java.math.BigInteger.ZERO, Bareiss.determinant(new long[][] {{1, 2}, {2, 4}}));
        // zero pivot in the middle of the elimination: [[1,2,3],[2,4,1],[3,5,7]] -> 1*(28-5) - 2*(14-3) + 3*(10-12) = 23 - 22 - 6 = -5
        assertEquals(java.math.BigInteger.valueOf(-5), Bareiss.determinant(new long[][] {{1, 2, 3}, {2, 4, 1}, {3, 5, 7}}));
        assertEquals(java.math.BigInteger.valueOf(9), Bareiss.determinant(new long[][] {{9}}));
        assertThrows(IllegalArgumentException.class, () -> Bareiss.determinant(new long[][] {{1, 2}}));
    }
}

package ae.linalg;

import static org.junit.jupiter.api.Assertions.*;

import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.Test;

class CharPolyTest {
    static Rational[] c(long... xs) {
        Rational[] r = new Rational[xs.length];
        for (int i = 0; i < xs.length; i++) {
            r[i] = Rational.of(xs[i]);
        }
        return r;
    }

    @Test
    void twoByTwoLiteral() {
        // det(xI - A) = x^2 - tr x + det = x^2 - 5x - 2 for [[1,2],[3,4]]
        assertArrayEquals(c(-2, -5, 1), CharPoly.coefficients(Matrix.of(new long[][] {{1, 2}, {3, 4}})));
    }

    @Test
    void threeByThreeLiteral() {
        // companion-like: [[0,1,0],[0,0,1],[6,-11,6]] has char poly x^3 - 6x^2 + 11x - 6 = (x-1)(x-2)(x-3)
        Matrix a = Matrix.of(new long[][] {{0, 1, 0}, {0, 0, 1}, {6, -11, 6}});
        assertArrayEquals(c(-6, 11, -6, 1), CharPoly.coefficients(a));
    }

    @Test
    void oneByOneAndIdentity() {
        assertArrayEquals(c(-7, 1), CharPoly.coefficients(Matrix.of(new long[][] {{7}})));
        // (x-1)^3 = x^3 - 3x^2 + 3x - 1
        assertArrayEquals(c(-1, 3, -3, 1), CharPoly.coefficients(Matrix.identity(3)));
    }

    @Test
    void rationalEigenvaluesWithMultiplicity() {
        Matrix a = Matrix.of(new long[][] {{0, 1, 0}, {0, 0, 1}, {6, -11, 6}});
        assertEquals(Map.of(Rational.of(1), 1, Rational.of(2), 1, Rational.of(3), 1), CharPoly.rationalEigenvalues(a));
        assertEquals(Map.of(Rational.ONE, 3), CharPoly.rationalEigenvalues(Matrix.identity(3)));
        // upper triangular with diagonal 2, 2, -1/2 : entries scaled so denominators appear
        Matrix t = Matrix.of(new long[][] {{4, 1, 0}, {0, 4, 3}, {0, 0, -1}}).times(Rational.of(1, 2));
        Map<Rational, Integer> ev = CharPoly.rationalEigenvalues(t);
        assertEquals(Map.of(Rational.of(2), 2, Rational.of(-1, 2), 1), ev);
    }

    @Test
    void irrationalRootsAreNotReported() {
        // x^2 - 5x - 2 has discriminant 33, no rational roots
        assertTrue(CharPoly.rationalEigenvalues(Matrix.of(new long[][] {{1, 2}, {3, 4}})).isEmpty());
        // rotation [[0,-1],[1,0]]: x^2+1, none
        assertTrue(CharPoly.rationalEigenvalues(Matrix.of(new long[][] {{0, -1}, {1, 0}})).isEmpty());
        // x^2 - 2 mixed with a rational root: diag block [[0,2],[1,0]] and 3 -> (x^2-2)(x-3)
        Matrix a = Matrix.of(new long[][] {{0, 2, 0}, {1, 0, 0}, {0, 0, 3}});
        assertEquals(Map.of(Rational.of(3), 1), CharPoly.rationalEigenvalues(a));
    }

    @Test
    void zeroEigenvalueHandledWithoutRationalRootDivisionByZero() {
        Matrix a = Matrix.of(new long[][] {{1, 1}, {1, 1}});   // x^2 - 2x = x(x-2)
        assertEquals(Map.of(Rational.ZERO, 1, Rational.of(2), 1), CharPoly.rationalEigenvalues(a));
        assertEquals(Map.of(Rational.ZERO, 2), CharPoly.rationalEigenvalues(Matrix.zero(2, 2)));
    }

    @Test
    void eigenspaceLiteral() {
        Matrix a = Matrix.of(new long[][] {{2, 1}, {0, 2}});   // defective: one eigenvector for 2
        List<Rational[]> basis = CharPoly.eigenspace(a, Rational.of(2));
        assertEquals(1, basis.size());
        assertArrayEquals(c(1, 0), basis.get(0));
        // diag(2,2) has a 2-dimensional eigenspace: control differing only by the off-diagonal entry
        assertEquals(2, CharPoly.eigenspace(Matrix.of(new long[][] {{2, 0}, {0, 2}}), Rational.of(2)).size());
        // a non-eigenvalue has an empty eigenspace
        assertTrue(CharPoly.eigenspace(a, Rational.of(3)).isEmpty());
    }
}

package ae.linalg;

import static org.junit.jupiter.api.Assertions.*;

import org.junit.jupiter.api.Test;

class LuTest {
    @Test
    void literalDecompositionNoSwap() {
        Matrix a = Matrix.of(new long[][] {{2, 1}, {4, 5}});
        Lu lu = Lu.decompose(a);
        assertEquals(Matrix.of(new long[][] {{1, 0}, {2, 1}}), lu.l());
        assertEquals(Matrix.of(new long[][] {{2, 1}, {0, 3}}), lu.u());
        assertEquals(Matrix.identity(2), lu.p());
        assertEquals(1, lu.sign());
    }

    @Test
    void swapRecordedInPermutationAndSign() {
        Matrix a = Matrix.of(new long[][] {{0, 1}, {2, 3}});
        Lu lu = Lu.decompose(a);
        assertEquals(Matrix.of(new long[][] {{0, 1}, {1, 0}}), lu.p());
        assertEquals(-1, lu.sign());
        assertEquals(lu.p().times(a), lu.l().times(lu.u()));
        assertEquals(Matrix.of(new long[][] {{2, 3}, {0, 1}}), lu.u());
    }

    @Test
    void singularMatrixStillDecomposes() {
        Matrix a = Matrix.of(new long[][] {{1, 2, 3}, {2, 4, 6}, {1, 0, 1}});
        Lu lu = Lu.decompose(a);
        assertEquals(lu.p().times(a), lu.l().times(lu.u()));
        assertThrows(SingularMatrixException.class, () -> lu.solve(new Rational[] {Rational.ONE, Rational.ONE, Rational.ONE}));
    }

    @Test
    void solveMatchesLiteral() {
        Matrix a = Matrix.of(new long[][] {{0, 2, 1}, {3, 1, 0}, {1, 0, 2}});
        Rational[] b = {Rational.of(5), Rational.of(5), Rational.of(5)};
        Rational[] x = Lu.decompose(a).solve(b);
        for (Rational xi : x) {
            assertNotNull(xi);
        }
        assertArrayEquals(b, a.apply(x));
        // det = -13 and the first unknown from Cramer: x0 = det[[5,2,1],[5,1,0],[5,0,2]]/-13 = 5*(2)-2*(10)+1*(-5) = -15 / -13
        assertEquals(Rational.of(15, 13), x[0]);
    }

    @Test
    void determinantFromLuAgreesWithElimination() {
        Matrix a = Matrix.of(new long[][] {{0, 2, 1}, {3, 1, 0}, {1, 0, 2}});
        assertEquals(Elimination.determinant(a), Lu.decompose(a).determinant());
        assertEquals(Rational.of(-13), Lu.decompose(a).determinant());
    }

    @Test
    void nonSquareRejected() {
        assertThrows(IllegalArgumentException.class, () -> Lu.decompose(Matrix.zero(2, 3)));
    }
}

package ae.linalg;

import static org.junit.jupiter.api.Assertions.*;

import java.math.BigInteger;
import org.junit.jupiter.api.Test;

class RationalTest {
    @Test
    void normalisesSignAndGcd() {
        Rational r = Rational.of(6, -8);
        assertEquals(BigInteger.valueOf(-3), r.num());
        assertEquals(BigInteger.valueOf(4), r.den());
        assertEquals("-3/4", r.toString());
        assertEquals(Rational.of(-3, 4), r);
        assertEquals(Rational.of(-3, 4).hashCode(), r.hashCode());
        assertEquals("5", Rational.of(10, 2).toString());
        assertEquals(Rational.ZERO, Rational.of(0, -7));
        assertEquals("0", Rational.of(0, -7).toString());
    }

    @Test
    void arithmeticLiterals() {
        Rational a = Rational.of(1, 2);
        Rational b = Rational.of(-2, 3);
        assertEquals(Rational.of(-1, 6), a.add(b));
        assertEquals(Rational.of(7, 6), a.sub(b));
        assertEquals(Rational.of(-1, 3), a.mul(b));
        assertEquals(Rational.of(-3, 4), a.div(b));
        assertEquals(Rational.of(2), a.inverse());
        assertEquals(Rational.of(8, 27), b.pow(3).negate());
        assertEquals(Rational.of(9, 4), b.pow(-2));
        assertEquals(Rational.ONE, b.pow(0));
    }

    @Test
    void divisionByZeroFails() {
        assertThrows(ArithmeticException.class, () -> Rational.of(1, 0));
        assertThrows(ArithmeticException.class, () -> Rational.ONE.div(Rational.ZERO));
        assertThrows(ArithmeticException.class, Rational.ZERO::inverse);
        assertThrows(ArithmeticException.class, () -> Rational.ZERO.pow(-1));
    }

    @Test
    void orderingIsByValueNotByParts() {
        assertTrue(Rational.of(1, 3).compareTo(Rational.of(1, 2)) < 0);
        assertTrue(Rational.of(-1, 3).compareTo(Rational.of(-1, 2)) > 0);
        assertEquals(0, Rational.of(2, 4).compareTo(Rational.of(1, 2)));
        assertEquals(-1, Rational.of(-5, 9).signum());
        assertEquals(0, Rational.ZERO.signum());
    }

    @Test
    void noOverflowWithHugeValues() {
        Rational big = Rational.of(Long.MAX_VALUE).mul(Rational.of(Long.MAX_VALUE));
        assertEquals(new BigInteger("85070591730234615847396907784232501249"), big.num());
        assertEquals(Rational.of(Long.MAX_VALUE), big.div(Rational.of(Long.MAX_VALUE)));
    }
}

package ae.linalg;

import static org.junit.jupiter.api.Assertions.*;

import org.junit.jupiter.api.Test;

class MatrixTest {
    static Matrix m(long[]... rows) {
        return Matrix.of(rows);
    }

    @Test
    void productLiteral() {
        Matrix a = m(new long[] {1, 2, 3}, new long[] {4, 5, 6});
        Matrix b = m(new long[] {7, 8}, new long[] {9, 10}, new long[] {11, 12});
        assertEquals(m(new long[] {58, 64}, new long[] {139, 154}), a.times(b));
        assertEquals(2, a.times(b).rows());
        assertEquals(2, a.times(b).cols());
    }

    @Test
    void transposeSwapsDimensionsAndEntries() {
        Matrix a = m(new long[] {1, 2, 3}, new long[] {4, 5, 6});
        Matrix t = a.transpose();
        assertEquals(3, t.rows());
        assertEquals(2, t.cols());
        assertEquals(Rational.of(6), t.get(2, 1));
        assertEquals(a, t.transpose());
    }

    @Test
    void fibonacciPower() {
        Matrix f = m(new long[] {1, 1}, new long[] {1, 0});
        // F(10)=55, F(11)=89, F(9)=34
        assertEquals(m(new long[] {89, 55}, new long[] {55, 34}), f.pow(10));
        assertEquals(Matrix.identity(2), f.pow(0));
        assertEquals(f, f.pow(1));
    }

    @Test
    void sumDifferenceScaleTrace() {
        Matrix a = m(new long[] {1, 2}, new long[] {3, 4});
        assertEquals(m(new long[] {2, 4}, new long[] {6, 8}), a.plus(a));
        assertEquals(Matrix.zero(2, 2), a.minus(a));
        assertEquals(Rational.of(5), a.trace());
        assertEquals(Rational.of(1, 2), a.times(Rational.of(1, 2)).get(0, 0));
        assertEquals(Rational.of(2), a.times(Rational.of(1, 2)).get(1, 1));
    }

    @Test
    void applyMultipliesColumnVector() {
        Matrix a = m(new long[] {1, 2}, new long[] {3, 4});
        Rational[] y = a.apply(new Rational[] {Rational.of(5), Rational.of(-1)});
        assertArrayEquals(new Rational[] {Rational.of(3), Rational.of(11)}, y);
    }

    @Test
    void rejectsBadShapes() {
        assertThrows(IllegalArgumentException.class, () -> m(new long[] {1, 2}, new long[] {3}));
        assertThrows(IllegalArgumentException.class, () -> Matrix.of(new long[0][0]));
        assertThrows(IllegalArgumentException.class, () -> Matrix.zero(0, 3));
        Matrix a = Matrix.zero(2, 3);
        assertThrows(IllegalArgumentException.class, () -> a.times(a));
        assertThrows(IllegalArgumentException.class, () -> a.plus(Matrix.zero(3, 2)));
        assertThrows(IllegalArgumentException.class, a::trace);
        assertThrows(IllegalArgumentException.class, () -> a.pow(2));
        assertThrows(IllegalArgumentException.class, () -> Matrix.identity(2).pow(-1));
        assertThrows(IllegalArgumentException.class, () -> a.apply(new Rational[] {Rational.ONE}));
        assertThrows(IndexOutOfBoundsException.class, () -> a.get(2, 0));
        assertThrows(IndexOutOfBoundsException.class, () -> a.get(0, -1));
    }

    @Test
    void isImmutable() {
        long[][] raw = {{1, 2}, {3, 4}};
        Matrix a = Matrix.of(raw);
        raw[0][0] = 99;
        assertEquals(Rational.ONE, a.get(0, 0));
        Rational[] row = a.row(0);
        row[0] = Rational.of(77);
        assertEquals(Rational.ONE, a.get(0, 0));
        Rational[] col = a.col(1);
        col[1] = Rational.of(77);
        assertEquals(Rational.of(4), a.get(1, 1));
    }

    @Test
    void toStringIsLineBased() {
        Matrix half = m(new long[] {1, -2}, new long[] {3, 4}).times(Rational.of(1, 2));
        assertEquals("1/2 -1\n3/2 2", half.toString());
    }

    @Test
    void raggedInEitherDirectionAndAliasingOfRationalInput() {
        // second row longer than the first, and (control) shorter
        assertThrows(IllegalArgumentException.class, () -> m(new long[] {1}, new long[] {2, 3}));
        assertThrows(IllegalArgumentException.class, () -> m(new long[] {1, 2}, new long[] {3}));
        Rational[][] raw = {{Rational.ONE, Rational.of(2)}, {Rational.of(3), Rational.of(4)}};
        Matrix a = Matrix.ofRational(raw);
        raw[0][0] = Rational.of(99);
        raw[1] = new Rational[] {Rational.ZERO, Rational.ZERO};
        assertEquals(Rational.ONE, a.get(0, 0));
        assertEquals(Rational.of(4), a.get(1, 1));
        assertThrows(IllegalArgumentException.class, () -> Matrix.ofRational(new Rational[][] {{Rational.ONE, null}}));
    }
}

package ae.linalg;

import static org.junit.jupiter.api.Assertions.*;

import java.util.List;
import org.junit.jupiter.api.Test;

class GramSchmidtTest {
    static Rational[] v(long... xs) {
        Rational[] r = new Rational[xs.length];
        for (int i = 0; i < xs.length; i++) {
            r[i] = Rational.of(xs[i]);
        }
        return r;
    }

    @Test
    void literalBasis() {
        List<Rational[]> out = GramSchmidt.orthogonalize(List.of(v(1, 1, 0), v(1, 0, 1), v(0, 1, 1)));
        assertEquals(3, out.size());
        assertArrayEquals(v(1, 1, 0), out.get(0));
        // (1,0,1) - (1/2)(1,1,0) = (1/2, -1/2, 1)
        assertArrayEquals(new Rational[] {Rational.of(1, 2), Rational.of(-1, 2), Rational.ONE}, out.get(1));
        // (0,1,1) - (1/2)(1,1,0) - ((1/2)/(3/2))(1/2,-1/2,1) = (-2/3, 2/3, 2/3)
        assertArrayEquals(new Rational[] {Rational.of(-2, 3), Rational.of(2, 3), Rational.of(2, 3)}, out.get(2));
    }

    @Test
    void dependentVectorsAreDropped() {
        List<Rational[]> out = GramSchmidt.orthogonalize(List.of(v(1, 2), v(2, 4), v(0, 1), v(5, 5)));
        assertEquals(2, out.size());
        assertEquals(Rational.ZERO, GramSchmidt.dot(out.get(0), out.get(1)));
    }

    @Test
    void zeroVectorsDroppedAndEmptyInput() {
        assertTrue(GramSchmidt.orthogonalize(List.of(v(0, 0), v(0, 0))).isEmpty());
        assertTrue(GramSchmidt.orthogonalize(List.of()).isEmpty());
    }

    @Test
    void projectionLiteral() {
        List<Rational[]> basis = GramSchmidt.orthogonalize(List.of(v(1, 0, 0), v(0, 1, 0)));
        assertArrayEquals(v(3, 4, 0), GramSchmidt.project(v(3, 4, 5), basis));
        // onto the line (1,1): (2,0) -> (1,1)
        assertArrayEquals(v(1, 1), GramSchmidt.project(v(2, 0), java.util.Collections.singletonList(v(1, 1))));
        assertArrayEquals(v(0, 0), GramSchmidt.project(v(2, 0), List.of()));
    }

    @Test
    void mismatchedLengthsRejected() {
        assertThrows(IllegalArgumentException.class, () -> GramSchmidt.orthogonalize(List.of(v(1, 2), v(1, 2, 3))));
        assertThrows(IllegalArgumentException.class, () -> GramSchmidt.dot(v(1), v(1, 2)));
    }
}
